public sealed class CheckoutCoordinator
{
    private readonly IPricingService _pricing;
    private readonly ITenderResolver _tenders;
    private readonly IFulfilmentPlanner _fulfilment;

    public CheckoutCoordinator(
        IPricingService pricing,
        ITenderResolver tenders,
        IFulfilmentPlanner fulfilment)
    {
        _pricing = pricing;
        _tenders = tenders;
        _fulfilment = fulfilment;
    }

    public CheckoutResult Complete(
        CheckoutSession session, Order order, Customer customer)
    {
        if (!session.HasBegun)
            return CheckoutResult.Failure(CheckoutError.NotStarted);

        var total = _pricing.Calculate(order, customer);
        var tender = _tenders.Resolve(order, customer, total);
        var tasks = _fulfilment.Plan(order);
        return CheckoutResult.Success(total, tender, tasks);
    }
}

